-- Part 2, phase 1 (feature/women-branch, continued): Tasks / Follow-ups.
--
-- A branch-scoped `tasks` table for admin follow-up work: manually created
-- by staff, or auto-generated by three trigger points (membership-expiry
-- reminders, new contact-form leads, and -- later, not wired yet -- a failed
-- Moyasar payment). Every business record in this app belongs to exactly one
-- branch (see 202609180001_women_branch's plans/offers treatment), so
-- branch_id is NOT NULL here too, same FK style (RESTRICT, not SET NULL --
-- a branch with open tasks can't be silently orphaned).
--
-- Polymorphic link to an optional related record (a membership, a message/
-- lead, later a payment) mirrors the existing `logs` table's target_table/
-- target_id shape (see src/db/schema.sql:212-225 and src/utils/logger.js) --
-- same idea, renamed linked_resource_type/linked_resource_id to read clearly
-- on a task ("this task is linked to membership #42"). No FK on the id half,
-- same reason logs.target_id has none: the type column decides which table
-- it points into, and that varies row to row.

CREATE TABLE IF NOT EXISTS tasks (
  id                   INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  branch_id            INT UNSIGNED NOT NULL,
  title                VARCHAR(200) NOT NULL,
  description          TEXT DEFAULT NULL,
  assigned_to          INT UNSIGNED DEFAULT NULL,
  due_date             DATETIME DEFAULT NULL,
  priority             ENUM('low','medium','high','urgent') NOT NULL DEFAULT 'medium',
  status               ENUM('open','in_progress','done','cancelled') NOT NULL DEFAULT 'open',
  linked_resource_type VARCHAR(100) DEFAULT NULL,
  linked_resource_id   INT UNSIGNED DEFAULT NULL,
  outcome_note         TEXT DEFAULT NULL,
  created_by           INT UNSIGNED DEFAULT NULL,
  updated_by           INT UNSIGNED DEFAULT NULL,
  created_at           DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at           DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_tasks_branch FOREIGN KEY (branch_id) REFERENCES branches(id) ON DELETE RESTRICT,
  CONSTRAINT fk_tasks_assigned_to FOREIGN KEY (assigned_to) REFERENCES admin_users(id) ON DELETE SET NULL,
  CONSTRAINT fk_tasks_created_by FOREIGN KEY (created_by) REFERENCES admin_users(id) ON DELETE SET NULL,
  CONSTRAINT fk_tasks_updated_by FOREIGN KEY (updated_by) REFERENCES admin_users(id) ON DELETE SET NULL,
  -- Dashboard widget query: open/overdue tasks for a branch, ordered by due date.
  INDEX idx_tasks_branch_status_due (branch_id, status, due_date),
  -- "My Tasks" quick filter: tasks assigned to the logged-in admin, by status.
  INDEX idx_tasks_assigned_status (assigned_to, status),
  -- Mirrors logs' idx_logs_target -- lookups/joins from a linked record's side.
  INDEX idx_tasks_linked_resource (linked_resource_type, linked_resource_id)
) ENGINE=InnoDB;

-- Per-branch, per-trigger toggle for auto-generated tasks, so autogeneration
-- doesn't spam a branch that doesn't want it. Reuses the existing branch-
-- scoped `settings` table (see 202609180002_settings_branch_scope) rather
-- than a new config table, matching the brief's "simplest approach that fits
-- this codebase". Defaults to enabled for every existing branch; a branch
-- created after this migration gets no row here and settingsRepository's
-- getSetting(..., fallback) already treats an absent key as "use the
-- fallback", so taskService defaults new branches to enabled the same way.
INSERT INTO settings (branch_id, key_name, value, type, label_en, label_ar)
SELECT b.id, 'task_autogen_expiring_memberships', 'true', 'boolean',
       'Auto-create tasks for expiring memberships', 'إنشاء مهام تلقائية لتنبيهات انتهاء العضوية'
FROM branches b
ON DUPLICATE KEY UPDATE key_name = VALUES(key_name);

INSERT INTO settings (branch_id, key_name, value, type, label_en, label_ar)
SELECT b.id, 'task_autogen_new_leads', 'true', 'boolean',
       'Auto-create tasks for new contact-form leads', 'إنشاء مهام تلقائية للاستفسارات الجديدة'
FROM branches b
ON DUPLICATE KEY UPDATE key_name = VALUES(key_name);
